# Let's solve Langford L(2,8) with backtracking
# Fixed: seq[4]=7, seq[8]=5, seq[10]=4 (0-indexed)

n = 8
length = 16

# We'll use backtracking
# For each value v (1..8), we need to place two occurrences at positions i and i+v+1

def solve():
    seq = [0] * length

    # Fixed assignments
    fixed = {4: 7, 8: 5, 10: 4}
    for i, v in fixed.items():
        seq[i] = v

    # Track which values have been placed
    placed = {v: [] for v in range(1, n+1)}

    # Pre-place fixed values
    for i, v in fixed.items():
        placed[v].append(i)

    # Check if any value already has both positions
    for v in range(1, n+1):
        if len(placed[v]) > 2:
            return None
        if len(placed[v]) == 2:
            p1, p2 = placed[v]
            if abs(p1 - p2) != v + 1:
                return None

    # For values with one placement, we know the other position
    for v in range(1, n+1):
        if len(placed[v]) == 1:
            p = placed[v][0]
            other1 = p + v + 1
            other2 = p - (v + 1)
            possible = []
            if 0 <= other1 < length and seq[other1] == 0:
                possible.append(other1)
            if 0 <= other2 < length and seq[other2] == 0:
                possible.append(other2)
            if len(possible) == 0:
                return None
            # We'll handle this in backtracking

    # Let's do backtracking
    # Order values by most constrained first
    values_to_place = [v for v in range(1, n+1) if len(placed[v]) < 2]

    def backtrack(idx):
        if idx == len(values_to_place):
            # Check all positions filled
            if all(seq[i] != 0 for i in range(length)):
                return seq.copy()
            return None

        v = values_to_place[idx]

        if len(placed[v]) == 1:
            # One position already placed, find the other
            p = placed[v][0]
            candidates = []
            other1 = p + v + 1
            other2 = p - (v + 1)
            if 0 <= other1 < length and seq[other1] == 0:
                candidates.append(other1)
            if 0 <= other2 < length and seq[other2] == 0:
                candidates.append(other2)

            for pos in candidates:
                seq[pos] = v
                placed[v].append(pos)
                result = backtrack(idx + 1)
                if result:
                    return result
                placed[v].pop()
                seq[pos] = 0
            return None
        else:
            # Need to place both occurrences
            for i in range(length):
                if seq[i] != 0:
                    continue
                j = i + v + 1
                if j >= length or seq[j] != 0:
                    continue
                # Place at i and j
                seq[i] = v
                seq[j] = v
                placed[v] = [i, j]
                result = backtrack(idx + 1)
                if result:
                    return result
                placed[v] = []
                seq[i] = 0
                seq[j] = 0
            return None

    return backtrack(0)

result = solve()
if result:
    print(f"Solution: {result}")
    # Verify
    from collections import Counter
    c = Counter(result)
    print(f"Counts: {dict(c)}")
    for v in range(1, n+1):
        positions = [i for i, val in enumerate(result) if val == v]
        print(f"Value {v}: positions {positions}, distance = {abs(positions[1]-positions[0])}, expected = {v+1}")
else:
    print("UNSATISFIABLE")
